Language: Python 3

import heapq


def dijkstra(graph, source):
    """graph: dict mapping vertex -> list of (neighbour, weight), weights >= 0.
    Returns a dict of shortest distances from source."""
    dist = {v: float('inf') for v in graph}
    dist[source] = 0
    pq = [(0, source)]                     # (distance, vertex) min-heap
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue                       # stale entry, already improved
        for v, w in graph[u]:
            nd = d + w
            if nd < dist[v]:               # relax edge (u, v)
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist


graph = {
    'A': [('B', 4), ('C', 1)],
    'B': [('D', 1)],
    'C': [('B', 2), ('D', 5)],
    'D': [],
}
print(dijkstra(graph, 'A'))
# Output: {'A': 0, 'B': 3, 'C': 1, 'D': 4}

Trace: pop A(0): C = 1, B = 4. Pop C(1): B improves to 1 + 2 = 3, D = 1 + 5 = 6. Pop B(3): D improves to 3 + 1 = 4. The remaining heap entries B(4) and D(6) are stale. Final: A 0, B 3, C 1, D 4.
Complexity: O((V + E) log V) with a binary heap; space O(V + E).

